CREATE TABLE schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE settings (id INTEGER PRIMARY KEY CHECK (id = 1), download_root TEXT, global_check_interval_minutes INTEGER DEFAULT 60 CHECK (global_check_interval_minutes IS NULL OR global_check_interval_minutes >= 1), download_concurrency INTEGER NOT NULL DEFAULT 1 CHECK (download_concurrency >= 1), updated_at TEXT NOT NULL);
CREATE TABLE proxies (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, proxy_url TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE channels (id INTEGER PRIMARY KEY AUTOINCREMENT, platform TEXT NOT NULL CHECK (platform = 'youtube'), extractor TEXT NOT NULL DEFAULT 'YoutubeTab' CHECK (extractor = 'YoutubeTab'), platform_channel_id TEXT NOT NULL, source_url TEXT NOT NULL, custom_name TEXT NOT NULL, custom_name_key TEXT NOT NULL UNIQUE, proxy_id INTEGER REFERENCES proxies(id) ON DELETE RESTRICT, check_interval_minutes INTEGER CHECK (check_interval_minutes IS NULL OR check_interval_minutes >= 1), paused_at TEXT, initial_synced_at TEXT NOT NULL, last_check_started_at TEXT, next_check_at TEXT, last_check_result TEXT CHECK (last_check_result IS NULL OR last_check_result IN ('success','no_updates','failed')), last_check_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (platform, platform_channel_id));
CREATE TABLE videos (id INTEGER PRIMARY KEY AUTOINCREMENT, channel_id INTEGER NOT NULL REFERENCES channels(id) ON DELETE RESTRICT, platform TEXT NOT NULL CHECK (platform = 'youtube'), platform_video_id TEXT NOT NULL, title TEXT NOT NULL, published_date TEXT NOT NULL, source_url TEXT NOT NULL, duration_seconds INTEGER CHECK (duration_seconds IS NULL OR duration_seconds >= 0), thumbnail_url TEXT, discovery_kind TEXT NOT NULL CHECK (discovery_kind IN ('historical','new')), discovered_at TEXT NOT NULL, UNIQUE (platform, platform_video_id));
CREATE TABLE notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, video_id INTEGER NOT NULL UNIQUE REFERENCES videos(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, read_at TEXT);
CREATE TABLE channel_checks (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL CHECK (kind IN ('initial','scheduled')), channel_id INTEGER REFERENCES channels(id) ON DELETE SET NULL, requested_url TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, result TEXT CHECK (result IS NULL OR result IN ('success','no_updates','failed')), new_video_count INTEGER NOT NULL DEFAULT 0 CHECK (new_video_count >= 0), failure_reason TEXT);
CREATE TABLE downloads (id INTEGER PRIMARY KEY AUTOINCREMENT, source_type TEXT NOT NULL CHECK (source_type IN ('channel','direct')), channel_id INTEGER REFERENCES channels(id) ON DELETE RESTRICT, video_id INTEGER REFERENCES videos(id) ON DELETE RESTRICT, source_url TEXT NOT NULL, platform TEXT NOT NULL CHECK (platform = 'youtube'), platform_video_id TEXT NOT NULL, title TEXT NOT NULL, published_date TEXT, network_mode TEXT NOT NULL CHECK (network_mode IN ('direct','proxy')), proxy_name TEXT, proxy_url_snapshot TEXT, target_subdirectory TEXT, advanced_options_json TEXT, status TEXT NOT NULL CHECK (status IN ('pending','downloading','running','completed','failed','canceled','interrupted')), output_path TEXT, failure_reason TEXT, progress_percent REAL CHECK (progress_percent IS NULL OR (progress_percent >= 0 AND progress_percent <= 100)), speed_text TEXT, eta_seconds INTEGER CHECK (eta_seconds IS NULL OR eta_seconds >= 0), exit_code INTEGER, created_at TEXT NOT NULL, started_at TEXT, finished_at TEXT, CHECK ((source_type='channel' AND channel_id IS NOT NULL AND video_id IS NOT NULL AND published_date IS NOT NULL) OR (source_type='direct' AND channel_id IS NULL AND video_id IS NULL)), CHECK ((network_mode='direct' AND proxy_name IS NULL AND proxy_url_snapshot IS NULL) OR (network_mode='proxy' AND proxy_name IS NOT NULL AND proxy_url_snapshot IS NOT NULL)), CHECK ((status='completed' AND output_path IS NOT NULL AND failure_reason IS NULL) OR (status IN ('failed','canceled','interrupted') AND failure_reason IS NOT NULL AND output_path IS NULL) OR (status IN ('pending','downloading','running') AND output_path IS NULL AND failure_reason IS NULL)));
CREATE INDEX idx_channels_due ON channels(last_check_started_at);
CREATE INDEX idx_videos_channel_date ON videos(channel_id, published_date DESC, id DESC);
CREATE INDEX idx_notifications_created ON notifications(created_at DESC, id DESC);
CREATE INDEX idx_channel_checks_channel_started ON channel_checks(channel_id, started_at DESC);
CREATE INDEX idx_downloads_status_created ON downloads(status, created_at, id);
CREATE INDEX idx_downloads_created ON downloads(created_at DESC, id DESC);
